         },
       ];

       function escapeHtml(value) {
         return value
           .replaceAll("&", "&amp;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;")
           .replaceAll("'", "&#39;");
       }

       function FeatureItem(icon, title, copy) {
         return `
           <li>
             <span class="feature-icon" aria-hidden="true">${icon}</span>
             <div>
               <strong>${title}</strong>
               <div>${copy}</div>
             </div>
           </li>
         `;
