             <p class="lead">
               Share the best way to reach you and we will follow up with the right
               specialist as quickly as possible.
             </p>
             <ul class="feature-list">
               ${FeatureItem("1", "Fast routing", "Your message reaches billing, product, or technical support without extra back-and-forth.")}
               ${FeatureItem("2", "Clear updates", "We keep replies concise, helpful, and easy to act on from any device.")}
               ${FeatureItem("3", "Human follow-up", "When a detail matters, our team contacts you directly using the information below.")}
             </ul>
           </section>
         `;
       }

       function FormField(field) {
         const describedBy = [];
         if (field.helperText) describedBy.push(`${field.id}-help`);
         return `
           <div class="form-field">
             <label class="form-label" for="${field.id}">
               ${field.label}${field.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
             </label>
             <input
               class="form-input"
               id="${field.id}"
               name="${field.id}"
               type="${field.type}"
               ${field.required ? "required" : ""}
               autocomplete="${field.autocomplete}"
               ${field.inputMode ? `inputmode="${field.inputMode}"` : ""}
               ${describedBy.length ? `aria-describedby="${describedBy.join(" ")}"` : ""}
               placeholder="${escapeHtml(field.placeholder)}"
             />
             ${field.helperText ? `<p class="helper-text" id="${field.id}-help">${field.helperText}</p>` : ""}
             <p class="field-error" id="${field.id}-error" hidden></p>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="form-panel" aria-labelledby="contact-form-title">
             <h2 class="panel-title" id="contact-form-title">Contact support</h2>
             <p class="panel-copy">Fields marked with an asterisk are required.</p>
             <form class="contact-form" id="contact-form" novalidate>
               <p class="required-note">We only ask for the details we need to reply.</p>
               ${fieldConfig.map(FormField).join("")}
               <p class="status-banner" id="visible-status" hidden></p>
               <p class="sr-only" id="form-status" role="status"></p>
               <button class="submit-button" type="submit">Send request</button>
             </form>
           </section>
         `;
       }

       function App() {
         return `
           <header class="page-shell page-header">
             <div class="brand">
               <span class="brand-mark" aria-hidden="true">A</span>
               <span>Acme Cloud</span>
             </div>
           </header>
           <main class="page-shell" id="main-content" tabindex="-1">
             <div class="page-layout">
               ${SupportHero()}
               ${ContactForm()}
             </div>
           </main>
         `;
       }

       const appRoot = document.getElementById("app");
       appRoot.innerHTML = App();

       const form = document.getElementById("contact-form");
       const visibleStatus = document.getElementById("visible-status");
       const politeStatus = document.getElementById("form-status");
       const touchedFields = new Set();

       function getFieldState(fieldId) {
         const input = document.getElementById(fieldId);
         const error = document.getElementById(`${fieldId}-error`);
         const help = document.getElementById(`${fieldId}-help`);
         return { input, error, help };
       }

       function clearFieldState(fieldId) {
         const { input, error, help } = getFieldState(fieldId);
         error.textContent = "";
         error.hidden = true;
         input.removeAttribute("aria-invalid");
         if (help) {
           input.setAttribute("aria-describedby", help.id);
         } else {
           input.removeAttribute("aria-describedby");
         }
       }

       function validateField(fieldId) {
         const field = fieldConfig.find((item) => item.id === fieldId);
         const { input, error, help } = getFieldState(fieldId);
         const value = input.value.trim();
         let message = "";

         if (field.required && !value) {
           message = `Error: Enter your ${field.label.toLowerCase()}.`;
         } else if (fieldId === "email" && value) {
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value)) {
             message = "Error: Enter a valid email address like name@example.com.";
           }
         } else if (fieldId === "phone" && value) {
           const phonePattern = /^[+]?[\d\s().-]{7,20}$/;
           if (!phonePattern.test(value)) {
             message = "Error: Enter a phone number using digits and optional separators like (555) 123-4567.";
           }
         }

         if (message) {
           error.textContent = message;
           error.hidden = false;
           input.setAttribute("aria-invalid", "true");
           const describedBy = [];
           if (help) describedBy.push(help.id);
           describedBy.push(error.id);
           input.setAttribute("aria-describedby", describedBy.join(" "));
         } else {
           error.textContent = "";
           error.hidden = true;
           input.removeAttribute("aria-invalid");
           if (help) {
             input.setAttribute("aria-describedby", help.id);
           } else {
             input.removeAttribute("aria-describedby");
           }
         }

         return !message;
       }

       function setStatus(message, kind) {
         politeStatus.textContent = "";
         window.requestAnimationFrame(() => {
           politeStatus.textContent = message;
         });

         if (!message) {
           visibleStatus.hidden = true;
           visibleStatus.textContent = "";
           visibleStatus.className = "status-banner";
           return;
         }

         visibleStatus.hidden = false;
         visibleStatus.textContent = message;
         visibleStatus.className = `status-banner ${kind}`;
       }

       fieldConfig.forEach((field) => {
         const { input } = getFieldState(field.id);
         input.addEventListener("blur", () => {
           touchedFields.add(field.id);
           validateField(field.id);
         });

         input.addEventListener("input", () => {
           if (touchedFields.has(field.id)) {
             validateField(field.id);
           }
           if (!visibleStatus.hidden) {
             setStatus("", "");
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         setStatus("", "");

         fieldConfig.forEach((field) => touchedFields.add(field.id));
         const invalidField = fieldConfig.find((field) => !validateField(field.id));

         if (invalidField) {
           setStatus("Please correct the highlighted fields and try again.", "error");
           document.getElementById(invalidField.id).focus();
           return;
         }

         setStatus("Your support request is ready to send. A specialist will contact you soon.", "success");
         form.reset();
         touchedFields.clear();
         fieldConfig.forEach((field) => clearFieldState(field.id));
       });
     </script>
   </body>
 </html>

